// World-space contact points on each shape
const FReal ContactWeight0 = Body0.InvM();
const FReal ContactWeight1 = Body1.InvM();
const FVec3 WorldContact0 = ShapeWorldTransform0.TransformPositionNoScale(FVec3(ManifoldPoint.ContactPoint.ShapeContactPoints[0]));
const FVec3 WorldContact1 = ShapeWorldTransform1.TransformPositionNoScale(FVec3(ManifoldPoint.ContactPoint.ShapeContactPoints[1]));
const FVec3 WorldContact = (ContactWeight0 * WorldContact0 + ContactWeight1 * WorldContact1) / (ContactWeight0 + ContactWeight1);
const FVec3f WorldRelativeContact0 = FVec3f(WorldContact - Body0.P());
const FVec3f WorldRelativeContact1 = FVec3f(WorldContact - Body1.P());

// World-space normal
const FVec3f WorldContactNormal = FVec3f(ShapeWorldTransform1.TransformVectorNoScale(FVec3(ManifoldPoint.ContactPoint.ShapeContactNormal)));

// World-space tangent U
FVec3f WorldContactTangentU = FVec3f::CrossProduct(FVec3f(0, 1, 0), WorldContactNormal);
if (!WorldContactTangentU.Normalize(FRealSingle(UE_KINDA_SMALL_NUMBER)))
{
	WorldContactTangentU = FVec3f::CrossProduct(FVec3f(1, 0, 0), WorldContactNormal);
	WorldContactTangentU = WorldContactTangentU.GetUnsafeNormal();
}

// Calculate contact velocity if we will need it below (restitution and/or first-contact for friction or initial depenetration)
const bool bNeedContactVelocity = (!ManifoldPoint.Flags.bHasStaticFrictionAnchor) || (Restitution > FRealSingle(0)) || ManifoldPoint.Flags.bInitialContact || CVars::bChaos_PBDCollisionSolver_Use1DFriction;
FVec3f ContactVel = FVec3(0);
FRealSingle ContactVelocityNormal = FRealSingle(0);
if (bNeedContactVelocity)
{
	const FVec3f ContactVel0 = Body0.V() + FVec3f::CrossProduct(Body0.W(), WorldRelativeContact0);
	const FVec3f ContactVel1 = Body1.V() + FVec3f::CrossProduct(Body1.W(), WorldRelativeContact1);
	ContactVel = ContactVel0 - ContactVel1;
	ContactVelocityNormal = FVec3f::DotProduct(ContactVel, WorldContactNormal);
	// Align TangentU with the relative sliding velocity direction,
	// Falls back to the geometric axis when sliding velocity is near zero
	FVec3f ContactVelTangent = ContactVel - ContactVelocityNormal * WorldContactNormal;
	if (ContactVelTangent.Normalize(FRealSingle(UE_KINDA_SMALL_NUMBER)))
	{
		WorldContactTangentU = ContactVelTangent;
	}
}

// TangentV is always perpendicular to both normal and TangentU
const FVec3f WorldContactTangentV = FVec3f::CrossProduct(WorldContactNormal, WorldContactTangentU);

// If we have contact data from a previous tick, use it to calculate the lateral position delta we need
// to apply to move the contacts back to their original relative locations (i.e., to enforce static friction).
// Otherwise, estimate the friction correction from the contact velocity.
// NOTE: quadratic shapes use the velocity-based path most of the time, unless the relative motion is very small.
FVec3f WorldFrictionDelta = FVec3f(0);
if (ManifoldPoint.Flags.bHasStaticFrictionAnchor)
{
	const FVec3 FrictionDelta0 = ShapeWorldTransform0.TransformPositionNoScale(FVec3(ManifoldPoint.ShapeAnchorPoints[0]));
	const FVec3 FrictionDelta1 = ShapeWorldTransform1.TransformPositionNoScale(FVec3(ManifoldPoint.ShapeAnchorPoints[1]));
	WorldFrictionDelta = FVec3f(FrictionDelta0 - FrictionDelta1);
}
else
{
	WorldFrictionDelta = ContactVel * Dt;
}

// The contact point error we are trying to correct in this solver
const FVec3f WorldContactDelta = FVec3f(WorldContact0 - WorldContact1);
FRealSingle WorldContactDeltaNormal = FVec3f::DotProduct(WorldContactDelta, WorldContactNormal);
FRealSingle WorldContactDeltaTangentU = FVec3f::DotProduct(WorldContactDelta + WorldFrictionDelta, WorldContactTangentU);
FRealSingle WorldContactDeltaTangentV = FVec3f::DotProduct(WorldContactDelta + WorldFrictionDelta, WorldContactTangentV);

FORCEINLINE_DEBUGGABLE void UpdateCollisionConstraintFromSolver(FPBDCollisionConstraint* Constraint, const Private::FPBDCollisionSolver& Solver, const FSolverReal Dt)
{
	Constraint->ResetSolverResults();

	// NOTE: We only put the non-pruned manifold points into the solver so the ManifoldPointIndex and
	// SolverManifoldPointIndex do not necessarily match. See GatherManifoldPoints
	int32 SolverManifoldPointIndex = 0;
	for (int32 ManifoldPointIndex = 0; ManifoldPointIndex < Constraint->NumManifoldPoints(); ++ManifoldPointIndex)
	{
		FSolverVec3 NetPushOut = FSolverVec3(0);
		FSolverVec3 NetImpulse = FSolverVec3(0);
		FSolverReal StaticFrictionRatio = FSolverReal(0);

		if (!Constraint->GetManifoldPoint(ManifoldPointIndex).Flags.bDisabled)
		{
			if (SolverManifoldPointIndex < Solver.NumManifoldPoints())
			{
				const Private::FPBDCollisionSolverManifoldPoint& SolverManifoldPoint = Solver.GetManifoldPoint(SolverManifoldPointIndex);

				NetPushOut =
					SolverManifoldPoint.NetPushOutNormal * SolverManifoldPoint.ContactNormal +
					SolverManifoldPoint.NetPushOutTangentU * SolverManifoldPoint.ContactTangentU +
					SolverManifoldPoint.NetPushOutTangentV * SolverManifoldPoint.ContactTangentV;

				NetImpulse =
					SolverManifoldPoint.NetImpulseNormal * SolverManifoldPoint.ContactNormal +
					SolverManifoldPoint.NetImpulseTangentU * SolverManifoldPoint.ContactTangentU +
					SolverManifoldPoint.NetImpulseTangentV * SolverManifoldPoint.ContactTangentV;

				StaticFrictionRatio = SolverManifoldPoint.StaticFrictionRatio;

				++SolverManifoldPointIndex;
			}
		}

		// NOTE: We call this even for points we did not run the solver for (but with zero results)
		Constraint->SetSolverResults(ManifoldPointIndex,
			NetPushOut,
			NetImpulse,
			StaticFrictionRatio,
			Dt);
	}
}

FORCEINLINE void ResetSolverResults()
{
	// NOTE: does not initalize any manifold point data. All properties will be written to in SetSolverResults
	//SavedManifoldPoints.SetNum(ManifoldPoints.Num());
	SavedManifoldPoints.Reset(ManifoldPoints.Num());
	ManifoldPointResults.SetNum(ManifoldPoints.Num());
	MinInitialPhi = 0;
}

/**
 * @brief Store the data from the solver that is retained between ticks for the specified manifold point or used by dependent systems (plasticity, breaking, etc.)
*/
FORCEINLINE void SetSolverResults(
	const int32 ManifoldPointIndex, 
	const FVec3f& NetPushOut, 
	const FVec3f& NetImpulse, 
	const FRealSingle StaticFrictionRatio,
	const FRealSingle Dt)
{
	const FManifoldPoint& ManifoldPoint = ManifoldPoints[ManifoldPointIndex];
	FManifoldPointResult& ManifoldPointResult = ManifoldPointResults[ManifoldPointIndex];

	// Save contact data for friction
	bool bInsideStaticFrictionCone = false;
	if (StaticFrictionRatio >= FRealSingle(1.0f - UE_KINDA_SMALL_NUMBER))
	{
		// StaticFrictionRatio ~= 1: Static friction held - we keep the same contacts points as-is for use next frame
		SavedManifoldPoints.Emplace(
			ManifoldPoint.ShapeAnchorPoints[0],
			ManifoldPoint.ShapeAnchorPoints[1],
			ManifoldPoint.InitialPhi
		);
		bInsideStaticFrictionCone = true;
	}
	else if (StaticFrictionRatio < FRealSingle(UE_KINDA_SMALL_NUMBER))
	{
		// StaticFrictionRatio ~= 0: No friction (or no contact/impulse) - discard the friction anchors
		// If we have a lot of manifold points, we don't store the previous position for these contacts because we assume
		// that there will be others that actually applied an impulse and will fall into the other two branches.
		// This is an optimization when we have to match the new contacts with the saved ones (see AssignSavedManifoldPoints)
		const int32 SmallNumManifoldPoints = 8;
		if (ManifoldPoints.Num() < SmallNumManifoldPoints)
		{
			SavedManifoldPoints.Emplace(
				ManifoldPoint.ContactPoint.ShapeContactPoints[0],
				ManifoldPoint.ContactPoint.ShapeContactPoints[1],
				ManifoldPoint.InitialPhi
			);
		}
	}
	else
	{
		// 0 < StaticFrictionRatio < 1: We exceeded the friction cone. Slide the friction anchor 
		// toward the last-detected contact position so that it sits at the edge of the friction cone.
		SavedManifoldPoints.Emplace(
			FVec3f::Lerp(ManifoldPoint.ContactPoint.ShapeContactPoints[0], ManifoldPoint.ShapeAnchorPoints[0], StaticFrictionRatio),
			FVec3f::Lerp(ManifoldPoint.ContactPoint.ShapeContactPoints[1], ManifoldPoint.ShapeAnchorPoints[1], StaticFrictionRatio),
			ManifoldPoint.InitialPhi
		);

FRealSingle FPBDCollisionConstraint::CalculateSavedManifoldPointDistanceSq(const FSavedManifoldPoint& SavedManifoldPoint, const FManifoldPoint& ManifoldPoint) const
{
	// If we have a vertex-plane (or vertex-vertex) contact, we want to know if we have the same vertex(es).
	// If we have and edge-edge contact, we want to know if we have the same edges.
	// But we don't know what type of contact we have, so for now...
	// If the contact point is in the same spot on one of the bodies, assume it is the same contact
	// @todo(chaos) - collision detection should provide the contact point types (vertex/edge/plane)
	const FVec3f DP0 = ManifoldPoint.ContactPoint.ShapeContactPoints[0] - SavedManifoldPoint.ShapeContactPoints[0];
	const FVec3f DP1 = ManifoldPoint.ContactPoint.ShapeContactPoints[1] - SavedManifoldPoint.ShapeContactPoints[1];

	// When only one shape is quadratic, we only look at the quadratic contact point so we don't identify
	// a sphere spinning on the spot as a stationary contact
	// @todo(chaos): we don't really need the quadratic special case any more
	if (IsQuadratic0() && !IsQuadratic1())
	{
		return DP0.SizeSquared();
	}
	else if (IsQuadratic1() && !IsQuadratic0())
	{
		return DP1.SizeSquared();
	}
	else
	{
		return FMath::Min(DP0.SizeSquared(), DP1.SizeSquared());
	}
}

int32 FPBDCollisionConstraint::FindSimpleSavedManifoldPoint(const int32 ManifoldPointIndex) const
{
	if (bChaos_Manifold_EnableFrictionRestore)
	{
		const FManifoldPoint& ManifoldPoint = ManifoldPoints[ManifoldPointIndex];
		if (!ManifoldPoint.Flags.bDisabled)
		{
			const int32 NumAllowedSavedPoints = SavedManifoldPoints.Num();
			const FRealSingle ExactDistanceToleranceSq = FMath::Square(Chaos_Manifold_FrictionExactPositionTolerance);
			const FRealSingle NearDistanceToleranceSq = FMath::Square(Chaos_Manifold_FrictionNearPositionTolerance);

			// Ignore points farther than NearDistanceTolerance
			FRealSingle BestDistanceSq = NearDistanceToleranceSq;

			int32 MatchAllowedPointIndex = INDEX_NONE;
			for (int32 PointIndex = 0; PointIndex < NumAllowedSavedPoints; ++PointIndex)
			{
				const int32 MatchPointIndex = (PointIndex + ManifoldPointIndex) % NumAllowedSavedPoints;
				const FSavedManifoldPoint& SavedManifoldPoint = SavedManifoldPoints[MatchPointIndex];
				const FRealSingle DistanceSq = CalculateSavedManifoldPointDistanceSq(SavedManifoldPoint, ManifoldPoint);

				// If this is an exact match, take the point without searching further
				if (DistanceSq < ExactDistanceToleranceSq)
				{
					BestDistanceSq = DistanceSq;
					MatchAllowedPointIndex = MatchPointIndex;
					break;
				}

				// If this is a close match, we may use it if we can't find a better one
				if (DistanceSq < BestDistanceSq)
				{
					BestDistanceSq = DistanceSq;
					MatchAllowedPointIndex = MatchPointIndex;
				}
			}
				return MatchAllowedPointIndex;
		}

}

