FORCEINLINE_DEBUGGABLE void FPBDCollisionSolver::CalculateContactVelocityError(
	const FPBDCollisionSolverManifoldPoint& ManifoldPoint,
	const FSolverReal DynamicFriction,
	const FSolverReal Dt,
	FSolverReal& OutContactVelocityDeltaNormal,
	FSolverReal& OutContactVelocityDeltaTangentU,
	FSolverReal& OutContactVelocityDeltaTangentV) const
{
	const FConstraintSolverBody& Body0 = SolverBody0();
	const FConstraintSolverBody& Body1 = SolverBody1();

	FSolverReal ContactVelN = -ManifoldPoint.ContactTargetVelocityNormal;
	FSolverReal ContactVelU = FSolverReal(0);
	FSolverReal ContactVelV = FSolverReal(0);

	// @todo(chaos): check for static or stationary kinematics?
	ContactVelN += FSolverVec3::DotProduct(Body0.V() - Body1.V(), ManifoldPoint.ContactNormal);
	ContactVelN += FSolverVec3::DotProduct(Body0.W(), ManifoldPoint.ContactRxNormal0);
	ContactVelN -= FSolverVec3::DotProduct(Body1.W(), ManifoldPoint.ContactRxNormal1);

	ContactVelU += FSolverVec3::DotProduct(Body0.V() - Body1.V(), ManifoldPoint.ContactTangentU);
	ContactVelU += FSolverVec3::DotProduct(Body0.W(), ManifoldPoint.ContactRxTangentU0);
	ContactVelU -= FSolverVec3::DotProduct(Body1.W(), ManifoldPoint.ContactRxTangentU1);

	ContactVelV += FSolverVec3::DotProduct(Body0.V() - Body1.V(), ManifoldPoint.ContactTangentV);
	ContactVelV += FSolverVec3::DotProduct(Body0.W(), ManifoldPoint.ContactRxTangentV0);
	ContactVelV -= FSolverVec3::DotProduct(Body1.W(), ManifoldPoint.ContactRxTangentV1);

	OutContactVelocityDeltaNormal = ContactVelN;
	OutContactVelocityDeltaTangentU = ContactVelU;
	OutContactVelocityDeltaTangentV = ContactVelV;
}

FORCEINLINE_DEBUGGABLE void FPBDCollisionSolver::CalculateContactVelocityErrorNormal(
	const FPBDCollisionSolverManifoldPoint& ManifoldPoint,
	FSolverReal& OutContactVelocityDeltaNormal) const
{
	const FConstraintSolverBody& Body0 = SolverBody0();
	const FConstraintSolverBody& Body1 = SolverBody1();

	FSolverReal ContactVelN = -ManifoldPoint.ContactTargetVelocityNormal;
	ContactVelN += FSolverVec3::DotProduct(Body0.V() - Body1.V(), ManifoldPoint.ContactNormal);
	ContactVelN += FSolverVec3::DotProduct(Body0.W(), ManifoldPoint.ContactRxNormal0);
	ContactVelN -= FSolverVec3::DotProduct(Body1.W(), ManifoldPoint.ContactRxNormal1);

	OutContactVelocityDeltaNormal = ContactVelN;

{
	if (NewNonFrequentData)
	{
		// Geometry may have changed, we need to remove the particle and its collisions from the graph
		Evolution.InvalidateParticle(Handle);

		Handle->SetNonFrequentData(*NewNonFrequentData);
	}

case EKinematicTargetMode::Position:
{
	// Move to kinematic target and update velocities to match
	// Target positions only need to be processed once, and we reset the velocity next frame (if no new target is set)
	FVec3 NewX;
	FRotation3f NewR;
	if (bIsLastStep)
	{
		NewX = KinematicTarget.GetPosition();
		NewR = KinematicTarget.GetRotation();
		KinematicTarget.SetMode(EKinematicTargetMode::Reset);
	}
	else
	{
		// as a reminder, stepfraction is the remaing fraction of the step from the remaining steps
		// for total of 4 steps and current step of 2, this will be 1/3 ( 1 step passed, 3 steps remains )
		NewX = FVec3::Lerp(CurrentX, KinematicTarget.GetPosition(), StepFraction);
		NewR = FRotation3f::Slerp(CurrentR, KinematicTarget.GetRotation(), decltype(FQuat4f::X)(StepFraction));
	}

	const bool bPositionChanged = !FVec3::IsNearlyEqual(NewX, CurrentX, UE_SMALL_NUMBER);
	const bool bRotationChanged = !FRotation3::IsNearlyEqual(NewR, CurrentR, UE_SMALL_NUMBER);
	bMoved = bPositionChanged || bRotationChanged;
	FVec3 NewV = FVec3(0);
	FVec3f NewW = FVec3f(0);
	if (Dt > MinDt)
	{
		if (bPositionChanged)
		{
			NewV = FVec3::CalculateVelocity(CurrentX, NewX, Dt);
		}
		if (bRotationChanged)
		{
			NewW = FRotation3f::CalculateAngularVelocity(CurrentR, NewR, static_cast<FRealSingle>(Dt));
		}
	}
	Particle.SetX(NewX);
	Particle.SetRf(NewR);
	Particle.SetV(NewV);
	Particle.SetWf(NewW);
	Particle.SetIsMovingKinematic();

	break;
}

pub fn integrate_positions(
    mut solver_bodies: Query<&mut SolverBody, Without<CustomPositionIntegration>>,
    time: Res<Time>,
    mut diagnostics: ResMut<SolverDiagnostics>,
) {
    let start = crate::utils::Instant::now();

    let delta_secs = time.delta_seconds_adjusted();

    solver_bodies.par_iter_mut().for_each(|body| {
        let SolverBody {
            linear_velocity,
            angular_velocity,
            delta_position,
            delta_rotation,
            ..
        } = body.into_inner();

        *delta_position += *linear_velocity * delta_secs;
        #[cfg(feature = "2d")]
        {
            // Note: We should probably use `add_angle_fast` here
            *delta_rotation = Rotation::radians(*angular_velocity * delta_secs) * *delta_rotation;
        }
        #[cfg(feature = "3d")]
        {
            delta_rotation.0 =
                Quaternion::from_scaled_axis(*angular_velocity * delta_secs) * delta_rotation.0;
        }
    });

    diagnostics.integrate_positions += start.elapsed();

pub fn playground_kinematic_velocity_bridge(
    time: Res<Time<Virtual>>,
    curve: Res<PlaygroundMovingCurve>,
    transforms: bevy::transform::helper::TransformHelper,
    mut platforms: Query<
        (&PlaygroundKinematic, &Position, &mut Rotation, Option<&ChildOf>, &mut LinearVelocity, &mut AngularVelocity),
        With<PlaygroundMovingObject>,
    >,
) {
    let delta = time.delta()
        .min(crate::source_physics_timing::SOURCE_MAX_PHYSICS_DELTA)
        .as_secs_f32();
    for (kinematic, position, mut rotation, parent, mut linear, mut angular) in &mut platforms {
        match kinematic.kind {
            PlaygroundKinematicKind::MoveSpline { duration, start, end } => {
                let target = crate::extensions::playground::moving_object_position(
                    &curve, start, end, time.elapsed_secs(), duration,
                );
                linear.0 = if delta > 0.0 {
                    (target - position.0) / delta
                } else {
                    Vec3::ZERO
                };
                angular.0 = Vec3::ZERO;
            }
            PlaygroundKinematicKind::RotateWorldTime { rate_yzx_radians } => {
                linear.0 = Vec3::ZERO;
                let parent_rotation = parent.and_then(|parent| transforms.compute_global_transform(parent.parent()).ok())
                    .map_or(kinematic.base_transform.rotation, |parent| parent.rotation());
                let target = parent_rotation * crate::extensions::playground::rotating_object_rotation(rate_yzx_radians, time.elapsed_secs());
                let mut difference = (target * rotation.0.conjugate()).normalize();
                if difference.w < 0.0 { difference = -difference; }
                if delta > 0.0 {
                    angular.0 = difference.to_scaled_axis() / delta;
                } else {
                    angular.0 = Vec3::ZERO;
                    rotation.0 = target;
                }
            }
        }
    }
}
